def esc(s): return html.escape(s, quote=True)


def clean_urls(doc):
    def repl(m):
        pre, path, suffix = m.group(1), m.group(2), m.group(3) or ""
        seg = path.split("/")
        if seg and seg[-1] == "index":
            seg = seg[:-1]
        clean = "/" + "/".join(seg)
        if clean != "/" and not clean.endswith("/"):
            pass
        return 'href="' + clean + suffix + '"'
    return re.sub(r'href="((?:\.\./|\./)?)([a-z0-9\-/]+)\.html([?#][^"]*)?"', lambda m: repl(m), doc)

