def _lslug(h):
    return re.sub(r"[^a-z0-9]+", "-", h.lower()).strip("-")

def legal_page(kind, title, sections):
    toc = "".join(f'<a href="#{_lslug(h)}" data-toc="{_lslug(h)}">{esc(h)}</a>' for h, _ in sections)
    out = []
    for h, blocks in sections:
        out.append(f'<section class="legal-sec" id="{_lslug(h)}"><h2 class="legal-h">{esc(h)}</h2>')
        for kind_b, content in blocks:
            if kind_b == "p":
                out.append(f'<p class="legal-p">{content}</p>')
            else:
                out.append('<ul class="legal-ul">' + "".join(f"<li>{i}</li>" for i in content) + "</ul>")
        out.append("</section>")
    extra = ""
    if kind == "refund":
        extra = """
<div class="stagecards">
<div class="stagecard"><span class="stagecard-k">Stage 1</span><b>Before work begins</b><p>You cancel before our specialists start on your file.</p><span class="stagecard-r full">Full refund</span></div>
<div class="stagecard"><span class="stagecard-k">Stage 2</span><b>Checking, not submitted</b><p>Our document check has begun, but nothing has gone to the authority.</p><span class="stagecard-r part">Service fee less work done</span></div>
<div class="stagecard"><span class="stagecard-k">Stage 3</span><b>Submitted to the authority</b><p>Your application - and the official fee - are with the Saudi authority.</p><span class="stagecard-r none">Official fee non-refundable</span></div>
</div>"""
    elif kind == "privacy":
        extra = """
<div class="glancebox"><b>At a glance</b><ul>
<li>We collect only what your application needs - passport, photo, contact and travel details.</li>
<li>It goes to the Saudi authorities and your insurer, never to advertisers. We never sell personal information.</li>
<li>You can ask what we hold, and ask for it to be corrected or deleted, at any time.</li>
</ul></div>"""
    elif kind == "terms":
        extra = """
<div class="glancebox"><b>The short version</b><ul>
<li>We are a private Dubai service that prepares and submits Saudi visa applications - we are not the Saudi government, and we do not decide visas.</li>
<li>Your total is confirmed in writing before you pay: official fee plus our service fee.</li>
<li>Decisions and timings after submission belong to the Saudi authorities.</li>
<li>Refunds follow the stage of your application - see the Refund Policy.</li>
</ul></div>"""
    questions = f"""
<div class="legal-questions">
<div><b>Still have questions?</b><p>Reach our team and we will walk you through anything on this page.</p></div>
<div class="legal-q-btns"><a class="btn wa" href="{WA}" target="_blank" rel="noopener">WhatsApp us</a><a class="btn ghost" href="mailto:{EMAIL}">{EMAIL}</a></div>
</div>"""
    body = pagehero("Legal", title, "The plain-English version - the same terms our team works to.", "desert.jpg") + f"""
<section><div class="wrap legal-grid">
<aside class="legal-side"><div class="legal-toc"><span class="legal-toc-k">On this page</span>{toc}</div></aside>
<div class="legal-main"><p class="legal-updated">Last updated: 6 November 2026</p>{extra}{"".join(out)}{questions}</div>
</div></section>"""
    return chrome(title, title + " for visit-saudi.ae, operated by Brightlink Management Consultancy LLC, Dubai.", body)

