def visa_detail_page(v):
    pts = "".join(f"<li>{esc(x)}</li>" for x in v["points"])
    docs = "".join(f"<li>{esc(x)}</li>" for x in v["docs"])
    others = [x for x in VISAS if x["id"] != v["id"] and x["cat"] == v["cat"]][:3] or [x for x in VISAS if x["id"] != v["id"]][:3]
    rel = "\n".join(vcard(x, prefix="../") for x in others)
    deep = ""
    if v["id"] in DEEP:
        fq = DEEP_FAQS.get(v["id"], [])
        faq_html = "".join(f"<h3>{esc(q)}</h3><p>{esc(a)}</p>" for q, a in fq)
        schema = ""
        if fq:
            import json as _json
            schema = '<script type="application/ld+json">' + _json.dumps({"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}} for q, a in fq]}, ensure_ascii=False) + "</script>"
        deep = DEEP[v["id"]] + ('<section class="deepsec"><div class="wrap" style="max-width:900px"><h2>Frequently asked questions</h2>' + faq_html + '</div></section>' if fq else '') + schema
    body = f"""
<section style="padding:52px 0 30px"><div class="wrap" style="display:grid;grid-template-columns:1.05fr .95fr;gap:38px">
<div><div class="crumb" style="color:var(--gold)"><a href="../visa-types.html">Visa types</a> &nbsp;/&nbsp; {esc(v['tag'])}</div>
<h1 style="margin-bottom:12px">{esc(v['name'])}</h1>
<p class="lead">{esc(v['blurb'])}</p>
<p style="margin-top:12px;font-weight:800;color:var(--green)">{esc(v['meta'])}</p>
<h3 style="margin:26px 0 10px">Good to know</h3>
<ul style="margin-left:20px">{pts}</ul>
<div style="display:flex;gap:11px;flex-wrap:wrap;margin-top:26px"><a class="btn gold" href="../apply.html?visa={v['id']}">Apply for this visa</a><a class="btn ghost" href="../eligibility.html">Check eligibility first</a><a class="btn wa" href="https://wa.me/971566556645?text={quote('Hello, I am interested in the ' + v['name'] + '. Please guide me.')}" target="_blank" rel="noopener">WhatsApp about this visa</a></div>
</div>
<div><img src="../{v['img']}" alt="{esc(v['name'])}" style="border-radius:18px;height:280px;width:100%;object-fit:cover;margin-bottom:16px">
<div class="summary"><b style="display:block;margin-bottom:8px">Documents you will need</b><ul>{docs}</ul></div>
<div class="totalbox"><h4>What your total includes</h4><div class="tbgrid"><div class="tcell"><span class="tic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 22h18"/><path d="M6 18v-7"/><path d="M10 18v-7"/><path d="M14 18v-7"/><path d="M18 18v-7"/><path d="m12 2 8 5H4z"/></svg></span><b>Official Saudi fee</b><span>Includes the mandatory medical insurance</span></div><span class="top">+</span><div class="tcell"><span class="tic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-3.6 8-10V5l-8-3-8 3v7c0 6.4 8 10 8 10z"/><path d="m9 11.5 2 2 4-4.5"/></svg></span><b>Our service fee</b><span>Specialist check, submission and live tracking</span></div><span class="top">=</span><div class="tcell gold"><span class="tic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2h12v20l-2-1.3-2 1.3-2-1.3L10 22l-2-1.3L6 22z"/><path d="M9 8h6"/><path d="M9 12h6"/></svg></span><b>Your total</b><span class="tb-total">Confirmed in writing before you pay anything</span></div></div></div>
</div></div></section>
{deep}
{consult_section('../', v['id'])}
<section style="background:var(--sand)"><div class="wrap">
<div class="section-head rv"><h2>Related visas</h2></div>
<div class="cards">{rel}</div>
</div></section>"""
    return chrome(v["name"] + " - Saudi Arabia", v["blurb"] + " " + v["meta"] + ". Apply online with specialist document checks and live tracking.", body, prefix="../", ogimg=v["img"])


