def cslug(name):
    return re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")
def croute(name):
    if name in ELIGIBLE_PY: return "evisa"
    if name in GCC_NATS: return "gcc"
    return "sponsored"
def the_name(name):
    return ("the " + name) if name in THE_C else name
BADGE = {"evisa": ("ev", "eVisa online"), "gcc": ("gcc", "Visa-free entry"), "sponsored": ("sp", "Sponsored route")}

def chips_html(prefix=""):
    out = []
    for name, code in COUNTRIES:
        cls, label = BADGE[croute(name)]
        out.append(f'''<a class="cchip" data-name="{esc(name.lower())}" title="{esc(name)}" href="{prefix}countries/{cslug(name)}.html"><img class="cflag" src="https://flagcdn.com/w160/{code}.png" alt="" loading="lazy" onerror="this.remove()"><span class="cname">{esc(name)}</span><svg class="carr" viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12h15M13 6l6 6-6 6"/></svg></a>''')
    return "\n".join(out)

