def region_of(iso):
    w = WORLDMAP.get(iso)
    if w: return w["r"]
    d = WORLDDOTS.get(iso)
    return d[2] if d else ""

def embassies_page():
    cards = []
    _paths = ['<path class="land" d="%s"/>' % WORLDLAND]
    for cname2, ccode2 in COUNTRIES:
        iso2 = ccode2.lower()
        sub2 = MISSIONS.get(iso2) or ''
        w2 = WORLDMAP.get(iso2)
        if w2:
            _paths.append('<path class="cty%s" data-iso="%s" data-name="%s" data-region="%s" data-mission="%s" data-slug="%s" d="%s"><title>%s</title></path>' % (' host' if iso2 == 'sa' else '', iso2, esc(cname2), w2['r'], sub2, cslug(cname2), w2['d'], esc(cname2)))
        elif iso2 in WORLDDOTS:
            _x, _y, _r = WORLDDOTS[iso2]
            _paths.append('<circle class="cty dot" cx="%s" cy="%s" r="6.5" data-iso="%s" data-name="%s" data-region="%s" data-mission="%s" data-slug="%s"><title>%s</title></circle>' % (_x, _y, iso2, esc(cname2), _r, sub2, cslug(cname2), esc(cname2)))
    _chips = ''.join('<button type="button" class="embchip%s" data-region="%s">%s</button>' % (' active' if rv == 'all' else '', rv, lbl) for rv, lbl in [('all', 'All countries'), ('europe', 'Europe'), ('asia', 'Asia &amp; Middle East'), ('africa', 'Africa'), ('namerica', 'North America'), ('samerica', 'South America'), ('oceania', 'Oceania')])
    MAPBLOCK = '<div class="embchips">%s</div><div class="embmap-card"><svg id="embMap" viewBox="0 0 960 500" role="group" aria-label="Interactive world map - select a country">%s</svg></div>' % (_chips, ''.join(_paths))
    for cname, ccode in COUNTRIES:
        iso = ccode.lower()
        flag = '<img src="https://flagcdn.com/w80/%s.png" alt="" loading="lazy">' % iso
        route = '<a href="countries/%s.html">Your visa route from %s &rarr;</a>' % (cslug(cname), esc(cname))
        sub = MISSIONS.get(iso)
        if sub:
            links = '<a href="https://%s.saudiembassy.sa" target="_blank" rel="noopener"><b>Official embassy website</b> &#8599;</a>' % sub + route
            cards.append('<div class="ecard" data-name="%s" data-iso="%s" data-region="%s"><div class="ename">%s<span>%s</span></div><div class="elinks">%s</div></div>' % (esc(cname.lower()), iso, region_of(iso), flag, esc(cname), links))
        else:
            links = '<span class="enom">No mission website listed for this country.</span><a href="https://saudiembassy.sa" target="_blank" rel="noopener"><b>Official embassy directory</b> &#8599;</a>' + route
            cards.append('<div class="ecard" data-name="%s" data-iso="%s" data-region="%s"><div class="ename">%s<span>%s</span></div><div class="elinks">%s</div></div>' % (esc(cname.lower()), iso, region_of(iso), flag, esc(cname), links))
    body = pagehero("Embassies", "Saudi embassies & consulates worldwide",
      "Find the official Saudi mission for your country. One thing first, because it matters: the embassies are the Saudi government's - we are a private visa service in Dubai. This page simply points you to the right official door.", "riyadh.webp")
    body += """<section class="section"><div class="wrap">
<h2 class="sec-title">When do you actually need an embassy?</h2>
<p class="sec-sub">Most travellers never do - the eVisa, visa on arrival and sponsored routes cover the great majority of journeys, and you can <a href="eligibility.html">check your route</a> in under a minute. A Saudi mission is the right door for these:</p>
<div class="needgrid">
<div class="need"><h3>Embassy-route applications</h3><p>Some visa types and nationalities are handled in person by a Saudi embassy or consulate. If your route says \u201cembassy\u201d, the mission for your country of residence is where that application belongs.</p></div>
<div class="need"><h3>Document attestation</h3><p>Saudi missions attest documents - degrees, marriage and birth certificates, commercial papers - for use inside the Kingdom. Attestation is the mission's own service, arranged with them directly.</p></div>
<div class="need"><h3>Saudi citizens abroad</h3><p>For Saudi citizens living or travelling abroad, the embassy is their government's front desk: consular help, emergencies and passport services.</p></div>
</div></div></section>"""
    body += """<section class="section embsec emblast"><div class="wrap">
<h2 class="sec-title">Find your country's Saudi mission</h2>
<p class="sec-sub">Click your country on the map - or search for it - to open its page: your visa route, the documents you need, and the official Saudi mission website for your country, all in one place. %d countries have their own mission website on the Saudi government's domains (saudiembassy.sa); for the rest, the official embassy directory shows which mission covers you.</p>
%s
<div class="embsearch"><input type="search" id="embSearch" placeholder="Search your country..." aria-label="Search your country" autocomplete="off"><div class="embsugg" id="embSugg" hidden></div></div>
<p class="embhint">Tip: on a phone, the search is the fastest way to your country - or tap a region to zoom the map in.</p>
</div></section>""" % (len(MISSIONS), MAPBLOCK)
    body += cta_band()
    return chrome("Saudi Embassies & Consulates Worldwide | visit-saudi.ae",
      "Find the official Saudi embassy or consulate for your country - links to the Saudi government's own mission websites, plus your visa route from every country.",
      body)




